import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api';
import { Line } from 'react-chartjs-2';
import { Activity } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      try {
        const res = await getFiles();
        if (mounted) setFiles(res.data || []);
      } catch (err) {
        console.error(err);
      }
    };

    load();
    return () => { mounted = false; };
  }, []);

  const getTotal = (f) =>
    f?.metrics?.total_ms ?? f?.metrics?.total ?? 0;

  // ================= SEPARATE BY MODE =================
  const pqcFiles = files.filter(f => f.mode === "hybrid");
  const rsaFiles = files.filter(f => f.mode === "rsa");

  // ================= TRUE INDEPENDENT START =================
  const maxLength = Math.max(pqcFiles.length, rsaFiles.length);

  const labels = Array.from({ length: maxLength }, (_, i) => `Run ${i + 1}`);

  const pqcValues = pqcFiles.map(f => getTotal(f));
  const rsaValues = rsaFiles.map(f => getTotal(f));

  const lineChartData = {
    labels,
    datasets: [
      {
        label: "Hybrid PQC",
        data: pqcValues,
        borderColor: "#00ff9d",
        backgroundColor: "#00ff9d",
        borderWidth: 2,
        tension: 0.4,
        spanGaps: false
      },
      {
        label: "RSA Baseline",
        data: rsaValues,
        borderColor: "#a855f7",
        backgroundColor: "#a855f7",
        borderWidth: 2,
        tension: 0.4,
        spanGaps: false
      }
    ]
  };

  const avgPqc = pqcFiles.length
    ? (pqcFiles.reduce((a, f) => a + getTotal(f), 0) / pqcFiles.length).toFixed(2)
    : "0.00";

  const avgRsa = rsaFiles.length
    ? (rsaFiles.reduce((a, f) => a + getTotal(f), 0) / rsaFiles.length).toFixed(2)
    : "0.00";

  return (
    <div className="p-8 flex-1 min-h-0 space-y-6 overflow-y-auto custom-scrollbar">

      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <div>
          <h2 className="text-2xl font-bold text-white">
            Performance Monitor
          </h2>
          <p className="text-gray-500 text-xs font-mono uppercase">
            Comparative Analysis Engine
          </p>
        </div>

        <div className="text-right">
          <span className="text-xs text-gray-500 uppercase">
            Total Files
          </span>
          <p className="text-2xl font-mono text-white">
            {files.length}
          </p>
        </div>
      </div>

      {/* GRAPH */}
      <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
        <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2">
          <Activity size={16} />
          Encryption Latency Comparison
        </h3>

        <div className="h-80">
          <Line
            data={lineChartData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                legend: {
                  labels: { color: '#fff' }
                },
                tooltip: {
                  callbacks: {
                    title: (items) => {
                      const index = items[0].dataIndex;
                      const datasetIndex = items[0].datasetIndex;

                      if (datasetIndex === 0 && pqcFiles[index])
                        return pqcFiles[index].filename;

                      if (datasetIndex === 1 && rsaFiles[index])
                        return rsaFiles[index].filename;

                      return "";
                    }
                  }
                }
              },
              scales: {
                x: {
                  title: {
                    display: true,
                    text: "Execution Index (Independent per Mode)",
                    color: "#aaa"
                  },
                  ticks: { color: "#888" },
                  grid: { display: false }
                },
                y: {
                  beginAtZero: true,
                  title: {
                    display: true,
                    text: "Encryption Latency (ms)",
                    color: "#aaa"
                  },
                  ticks: { color: "#888" },
                  grid: { color: "#222" }
                }
              }
            }}
          />
        </div>
      </div>

      {/* AVERAGES */}
      <div className="grid grid-cols-2 gap-4">
        <Card
          title="Average PQC"
          value={`${avgPqc} ms`}
          color="text-neon-green"
        />
        <Card
          title="Average RSA"
          value={`${avgRsa} ms`}
          color="text-purple-400"
        />
      </div>

    </div>
  );
};

const Card = ({ title, value, color }) => (
  <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
    <span className="text-gray-400">{title}</span>
    <span className={`font-bold ${color}`}>{value}</span>
  </div>
);

export default Performance;
